"""A tiny GitHub client. Nothing to do with harbor accounts."""


class GitHubClient:
    def fetch_user(self, login):
        return {"login": login, "site_admin": login == "octo"}

    def fetch_user_repos(self, login):
        return [login + "/dotfiles"]
